import React, { useState, useEffect, useRef } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import './style.css';
import './style1.css';
import './style2.css';
import './style3.css';

// Obrazki
import bieg from './bieg.jpg';
import z2 from './z2.jfif';
import z3 from './z3.jpg';
import zdj1 from './zdj1.jpg';
import f4 from './4f.png';
import nike from './nike.png';
import jordan from './jordan.png';
import dzik from './dzik.jpg';

function App() {
  useEffect(() => {
    setTimeout(() => {
      function setCookie(name, value, days) {
        const expires = new Date(Date.now() + days * 864e5).toUTCString();
        document.cookie = `${name}=${encodeURIComponent(value)}; expires=${expires}; path=/`;
      }

      function getCookie(name) {
        return document.cookie.split('; ').reduce((acc, pair) => {
          const [k, v] = pair.split('=');
          return k === name ? decodeURIComponent(v) : acc;
        }, '');
      }

      function showConsentBanner() {
        if (document.getElementById('cookie-banner')) return;

        const banner = document.createElement('div');
        banner.id = 'cookie-banner';
        banner.innerHTML = `
          <div style="
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            background: #800020;
            color: white;
            padding: 16px;
            text-align: center;
            z-index: 99999;
            font-size: 14px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.2);">
            Ta strona używa plików cookie. Kontynuując, akceptujesz naszą politykę prywatności.
            <button id="acceptCookies" style="
              margin-left: 16px;
              padding: 8px 16px;
              background: #ffbf00;
              color: #1e1e1e;
              font-weight: bold;
              border: none;
              border-radius: 4px;
              cursor: pointer;">
              Akceptuję
            </button>
          </div>
        `;
        document.body.prepend(banner);

        document.getElementById('acceptCookies').addEventListener('click', () => {
          setCookie('cookieConsent', 'true', 365);
          banner.remove();
        });
      }

      function showWelcomeBack() {
        if (document.getElementById('welcomeBack')) return;

        const note = document.createElement('div');
        note.id = 'welcomeBack';
        note.innerHTML = `
          <div style="
            position: fixed;
            bottom: 20px;
            right: 20px;
            background: #fff;
            color: #800020;
            padding: 12px 20px;
            border: 2px solid #800020;
            border-radius: 10px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.1);
            font-weight: 600;
            font-size: 14px;
